package com.example.notificationservice.dto.response;
import java.time.LocalDateTime;
public class NotificationResponse { private Long notificationId; private Long userId; private String type; private String title; private String message; private Boolean isRead; private LocalDateTime sentAt; private LocalDateTime createdAt; public Long getNotificationId(){return notificationId;} public void setNotificationId(Long v){this.notificationId=v;} public Long getUserId(){return userId;} public void setUserId(Long v){this.userId=v;} public String getType(){return type;} public void setType(String v){this.type=v;} public String getTitle(){return title;} public void setTitle(String v){this.title=v;} public String getMessage(){return message;} public void setMessage(String v){this.message=v;} public Boolean getIsRead(){return isRead;} public void setIsRead(Boolean v){this.isRead=v;} public LocalDateTime getSentAt(){return sentAt;} public void setSentAt(LocalDateTime v){this.sentAt=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){this.createdAt=v;} }